1	// Gameplay tunables. Item/block data lives in items.ts, recipes in recipes.ts.
2	
3	// Player physics
4	export const PLAYER_HEIGHT = 1.8;
5	export const PLAYER_HALF_WIDTH = 0.3;
6	export const EYE_HEIGHT = 1.62;
7	export const GRAVITY = 26;
8	export const JUMP_VELOCITY = 8.2;
9	export const WALK_SPEED = 4.8;
10	export const SPRINT_SPEED = 12.8;
11	export const CROUCH_SPEED = 2.1;
12	export const WORLD_BORDER_PADDING = 1.2;
13	
14	// Player stats — Minecraft ranges: 20 HP shown as 10 hearts, 20 hunger as 10 drumsticks.
15	export const MAX_HEARTS = 20;
16	export const MAX_HUNGER = 20;
17	export const RESPAWN_SECONDS = 3;
18	export const HEALTH_REGEN_INTERVAL_SECONDS = 3;
19	// Health regen only runs at or above this hunger level; sprint needs more than SPRINT_MIN_HUNGER.
20	export const REGEN_MIN_HUNGER = 12;
21	export const SPRINT_MIN_HUNGER = 6;
22	// Hunger drain: one point per N blocks sprinted/walked, or per N jumps.
23	export const SPRINT_BLOCKS_PER_HUNGER = 100;
24	export const WALK_BLOCKS_PER_HUNGER = 300;
25	export const JUMPS_PER_HUNGER = 50;
26	
27	// Inventory
28	export const HOTBAR_SLOTS = 9;
29	export const INVENTORY_SLOTS = 36;
30	export const MAX_STACK_SIZE = 99;
31	// Storage slots in a placed chest (a 9x3 grid, like a Minecraft single chest).
32	export const CHEST_SLOTS = 27;
33	
34	// Mining & combat
35	export const MINE_REACH = 7;
36	export const MINING_RATE = 2.1; // progress per second per minePower
37	export const BARE_HAND_MINE_POWER = 0.8;
38	export const FIST_DAMAGE = 6;
39	export const ATTACK_REACH = 4.5;
40	export const ATTACK_AIM_DOT = 0.89; // how precisely the camera must face a mob
41	
42	// Day-night cycle (daylight ranges 0.04–1.0)
43	export const DAY_CYCLE_SECONDS = 240;
44	export const HOSTILE_SPAWN_BELOW_DAYLIGHT = 0.28;
45	export const SPIDER_AGGRO_BELOW_DAYLIGHT = 0.42;
46	export const HOSTILE_BURN_ABOVE_DAYLIGHT = 0.72;
47	
48	// Weather (cosmetic, transient — never persisted, never touches spawn balance).
49	// Time is split into fixed windows; a seeded hash of the window index decides
50	// whether it precipitates, and a triangular envelope ramps intensity in/out.
51	export const WEATHER_CYCLE_SECONDS = 180;
52	export const WEATHER_RAIN_FRACTION = 0.35;
53	
54	// Beds & sleep
55	// Sleeping is only allowed once it is night by the game's own definition (the
56	// hostile-spawn threshold). The fade is the frozen window before time skips;
57	// waking lands at this fraction of the cycle (a rising ~0.45 daylight morning).
58	export const SLEEP_ALLOWED_BELOW_DAYLIGHT = 0.28;
59	export const SLEEP_HOSTILE_RADIUS = 12;
60	export const SLEEP_FADE_SECONDS = 1.5;
61	export const WAKE_DAY_PHASE = 0.07;
62	
63	// Mob director
64	export const HOSTILE_SPAWN_INTERVAL_SECONDS = 10;
65	export const HOSTILE_CAP = 16;
66	
67	// Animal breeding. Feeding a passive animal puts it "in love" for a window; two
68	// in-love adults of the same kind within range spawn a baby that grows up after
69	// a timer. The passive cap and the wheat/seed cost bound the population.
70	export const BREED_FED_WINDOW_SECONDS = 30;
71	export const BREED_PARTNER_RADIUS = 3;
72	export const BREED_CHECK_INTERVAL_SECONDS = 0.5;
73	export const BABY_GROW_SECONDS = 90;
74	export const BABY_SCALE = 0.55;
75	export const PASSIVE_CAP = 24;
76	
77	// Random block ticks (crop growth; the system is extensible to other blocks).
78	// Each interval samples N columns within RADIUS of the player and runs the
