1	import * as THREE from "three";
2	import { VoxelWorld, type BlockId } from "@/lib/world";
3	import type { EquippedArmor, InventorySlot, MobKind, SaveData } from "@/lib/game/types";
4	import type { BlockChangeTracker } from "./blockChanges";
5	import type { Command } from "./commands";
6	
7	/** Session-only camera presentation mode; never persisted. Gameplay stays eye-relative in all modes. */
8	export type CameraMode = "first" | "third-rear" | "third-front";
9	
10	const CAMERA_MODE_CYCLE: readonly CameraMode[] = ["first", "third-rear", "third-front"];
11	
12	export function nextCameraMode(mode: CameraMode): CameraMode {
13	  return CAMERA_MODE_CYCLE[(CAMERA_MODE_CYCLE.indexOf(mode) + 1) % CAMERA_MODE_CYCLE.length];
14	}
15	
16	export type PlayerState = {
17	  position: THREE.Vector3;
18	  velocity: THREE.Vector3;
19	  /** Look direction; the renderer derives the camera from these. Order YXZ. */
20	  yaw: number;
21	  pitch: number;
22	  onGround: boolean;
23	};
24	
25	/** Simulation-side mob — no Three.js objects; visuals live in the renderer. */
26	export type MobState = {
27	  id: number;
28	  kind: MobKind;
29	  hostile: boolean;
30	  hp: number;
31	  /** Body center (ground + halfHeight), like the old group.position without bob. */
32	  position: THREE.Vector3;
33	  direction: THREE.Vector3;
34	  yaw: number;
35	  turnTimer: number;
36	  speed: number;
37	  /** Speed after aggro/flee multipliers this tick; renderer uses it for gait. */
38	  moveSpeed: number;
39	  detectRange: number;
40	  attackDamage: number;
41	  attackCooldown: number;
42	  attackTimer: number;
43	  halfHeight: number;
44	  bobSeed: number;
45	  /** Seconds left "in love" after being fed; pairs with another to breed. */
46	  fedTimer: number;
47	  /** Seconds left as a baby; > 0 means a scaled-down, no-drop juvenile. */
48	  ageTimer: number;
49	};
50	
51	export type MiningState = {
52	  /** "x,y,z" of the block being mined, or "" when idle. */
53	  targetKey: string;
54	  progress: number;
55	};
56	
57	/** Throttled (~4 Hz) readout for the F3 overlay; null while the overlay is closed. */
58	export type DebugInfo = {
59	  x: number;
60	  y: number;
61	  z: number;
62	  daylight: number;
63	};
64	
65	export type GameTimers = {
66	  voidTimer: number;
67	  regenTimer: number;
68	  sprintDistanceBudget: number;
69	  walkDistanceBudget: number;
70	  jumpBudget: number;
71	  stuckTimer: number;
72	  hostileSpawnTimer: number;
73	  daylightHudTimer: number;
74	  debugHudTimer: number;
75	  randomTickTimer: number;
76	  breedTimer: number;
77	};
78	
79	export type WeatherKind = "clear" | "rain" | "snow";
80	export type WeatherState = { kind: WeatherKind; intensity: number };
81	
82	export type GameState = {
83	  world: VoxelWorld;
84	  blockChanges: BlockChangeTracker;
85	  player: PlayerState;
86	  inventory: InventorySlot[];
87	  equippedArmor: EquippedArmor;
88	  selectedSlot: number;
89	  hearts: number;
90	  hunger: number;
91	  isDead: boolean;
92	  respawnTimer: number;
93	  inventoryOpen: boolean;
94	  /** Crafting station whose recipes are unlocked while the inventory is open, or null. */
95	  craftingStation: "furnace" | null;
96	  /** Chest contents (block-entities) keyed by the block's voxel index. */
97	  containers: Map<number, InventorySlot[]>;
98	  /** Voxel index of the chest open in the inventory panel, or null. */
99	  openContainerIndex: number | null;
100	  /** Frozen simulation behind the pause menu; only commands are processed. */
101	  paused: boolean;
102	  debugOpen: boolean;
103	  debugInfo: DebugInfo | null;
104	  cameraMode: CameraMode;
105	  capsActive: boolean;
106	  mobs: MobState[];
107	  nextMobId: number;
108	  dayClock: number;
109	  /** Derived from dayClock every tick; 0.04–1.0. */
110	  daylight: number;
111	  daylightPercent: number;
112	  /** Cosmetic, transient weather (never serialized). Drives precip + sky + audio. */
113	  weather: WeatherState;
114	  /** Seconds left in the sleep fade; > 0 freezes the sim until time skips. */
115	  sleepTimer: number;
116	  /** Bed respawn point (block coords), or null to respawn at a random land point. */
117	  spawnPoint: { x: number; y: number; z: number } | null;
118	  mining: MiningState;
119	  timers: GameTimers;
120	  /** Set when world geometry changed; the renderer rebuilds the mesh and clears it. */
121	  worldMeshDirty: boolean;
122	};
123	
124	export function createTimers(): GameTimers {
125	  return {
126	    voidTimer: 0,
127	    regenTimer: 0,
128	    sprintDistanceBudget: 0,
129	    walkDistanceBudget: 0,
130	    jumpBudget: 0,
131	    stuckTimer: 0,
132	    hostileSpawnTimer: 0,
133	    daylightHudTimer: 0,
134	    debugHudTimer: 0,
135	    randomTickTimer: 0,
136	    breedTimer: 0
137	  };
138	}
139	
140	/** Per-frame continuous input, owned by the input controller. */
141	export type FrameInput = {
142	  keys: ReadonlySet<string>;
143	  capsActive: boolean;
144	  leftMouseHeld: boolean;
145	  pointerLocked: boolean;
146	};
147	
148	export const IDLE_INPUT: FrameInput = {
149	  keys: new Set<string>(),
150	  capsActive: false,
151	  leftMouseHeld: false,
152	  pointerLocked: false
153	};
154	
155	/** The engine surface the UI may touch: intents in, save data out. */
156	export type GameApi = {
157	  dispatch(command: Command): void;
158	  serialize(): SaveData;
159	};
160	
161	/** Immutable view for the React UI, replaced only when a visible value changes. */
162	export type GameSnapshot = {
163	  /** Stable handle for dispatching intents; null until the engine exists. */
164	  api: GameApi | null;
165	  inventory: InventorySlot[];
